import {
  createElement,
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  type CSSProperties,
  type ReactElement,
  type ReactNode,
  type RefObject,
} from "react";
import { UniversalPlayer as CoreUniversalPlayer } from "../../core/player.js";
import { sourceToken } from "../../core/source.js";
import { createInitialState } from "../../core/state.js";
import type { PlayerOptions, PlayerSourceInput, PlayerState } from "../../core/types.js";

/** Inputs accepted by the React hook and component. */
export interface UseUniversalPlayerOptions extends Omit<PlayerOptions, "container"> {}

/** Imperative handle exposed by the React component. */
export interface UniversalPlayerHandle {
  readonly player: CoreUniversalPlayer | null;
  play(): Promise<void>;
  pause(): void;
  seek(time: number): void;
  load(source: PlayerSourceInput): Promise<void>;
}

/** Result returned by {@link useUniversalPlayer}. */
export interface UseUniversalPlayerResult {
  readonly hostRef: RefObject<HTMLDivElement | null>;
  readonly player: CoreUniversalPlayer | null;
  readonly state: PlayerState;
  play(): Promise<void>;
  pause(): void;
  seek(time: number): void;
  load(source: PlayerSourceInput): Promise<void>;
}

/** Props accepted by the React component. */
export interface UniversalPlayerProps extends UseUniversalPlayerOptions {
  readonly className?: string;
  readonly style?: CSSProperties;
  readonly children?: ReactNode;
}

/**
 * Creates and maintains one player for the lifetime of a component.
 *
 * Source changes are keyed through `sourceToken`, so equivalent URL values do
 * not reload. The player is destroyed on unmount (including Strict Mode's
 * simulated unmount).
 */
export function useUniversalPlayer(options: UseUniversalPlayerOptions): UseUniversalPlayerResult {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const playerRef = useRef<CoreUniversalPlayer | null>(null);
  const latest = useRef(options);
  const [player, setPlayer] = useState<CoreUniversalPlayer | null>(null);
  const [state, setState] = useState<PlayerState>(() => createInitialState(options));

  useEffect(() => {
    latest.current = options;
  });

  useEffect(() => {
    const host = hostRef.current;

    if (host === null) {
      return;
    }

    const { source: initialSource, ...rest } = latest.current;
    void initialSource;

    const instance = new CoreUniversalPlayer({ ...rest, container: host });
    playerRef.current = instance;
    setPlayer(instance);
    setState(instance.state);

    const unsubscribeState = instance.on("statechange", (next) => {
      setState(next);
    });
    const unsubscribeTime = instance.on("timeupdate", (event) => {
      setState((previous) => ({
        ...previous,
        currentTime: event.currentTime,
        duration: event.duration,
        buffered: event.buffered,
      }));
    });

    return () => {
      unsubscribeState();
      unsubscribeTime();
      instance.destroy();
      playerRef.current = null;
      setPlayer(null);
    };
  }, []);

  const token = sourceToken(options.source);

  useEffect(() => {
    const instance = playerRef.current;
    const source = latest.current.source;

    if (instance === null || source === undefined) {
      return;
    }

    void instance.load(source).catch(() => {
      // Failures are published through state and the `error` event.
    });
  }, [player, token]);

  useEffect(() => {
    if (player !== null) {
      player.setVolume(options.volume ?? 1);
    }
  }, [player, options.volume]);

  useEffect(() => {
    if (player !== null) {
      player.setMuted(options.muted ?? false);
    }
  }, [player, options.muted]);

  useEffect(() => {
    if (player !== null) {
      player.setPlaybackRate(options.playbackRate ?? 1);
    }
  }, [player, options.playbackRate]);

  const play = useCallback(async (): Promise<void> => {
    await playerRef.current?.play();
  }, []);

  const pause = useCallback((): void => {
    playerRef.current?.pause();
  }, []);

  const seek = useCallback((time: number): void => {
    playerRef.current?.seek(time);
  }, []);

  const load = useCallback(async (source: PlayerSourceInput): Promise<void> => {
    await playerRef.current?.load(source);
  }, []);

  return { hostRef, player, state, play, pause, seek, load };
}

/**
 * React host component.
 *
 * It renders only the host element; media, engine and controls live in the
 * framework-neutral core.
 */
export const UniversalPlayer = forwardRef<UniversalPlayerHandle, UniversalPlayerProps>(
  function UniversalPlayer(props, ref): ReactElement {
    const api = useUniversalPlayer(props);

    useImperativeHandle(
      ref,
      () => ({
        get player() {
          return api.player;
        },
        play: () => api.play(),
        pause: () => api.pause(),
        seek: (time: number) => api.seek(time),
        load: (source: PlayerSourceInput) => api.load(source),
      }),
      [api],
    );

    return createElement(
      "div",
      {
        ref: api.hostRef,
        className: props.className,
        style: props.style,
        "data-up-framework": "react",
        "data-up-status": api.state.status,
      },
      props.children,
    );
  },
);

UniversalPlayer.displayName = "UniversalPlayer";
